 public static void Finish(){var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();var scene=m.gameObject.scene;if(!EditorSceneManager.SaveScene(scene,"Logs/JJinCity-before-venue-seating-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true))throw new Exception("Backup failed");
