 public static void Preview(){var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();bool active=m.actors.activeSelf;m.actors.SetActive(true);var g=new GameObject("Temporary venue preview");var cam=g.AddComponent<Camera>();var rt=new RenderTexture(1280,720,24);var prev=RenderTexture.active;try{cam.transform.position=m.observeStand.position+Vector3.up*1.8f;cam.transform.LookAt(m.target.position+Vector3.up);cam.fieldOfView=65;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes("Logs/Venue-interior.png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{m.actors.SetActive(active);RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
